#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

banner "Max as a Linear app (actor=app)"

# Run from the root of the main checkout: Max's threads and his daily status
# read the main checkout's .env there.
LINEAR_API="https://api.linear.app"

# _max_token — prints a fresh client-credentials token for the Max app.
# Linear: request a new token per run, never persist it (about 30 days valid).
_max_token() {
  curl -fsS -u "${LINEAR_MAX_CLIENT_ID}:${LINEAR_MAX_CLIENT_SECRET}" \
    -d grant_type=client_credentials -d scope=read,write \
    "$LINEAR_API/oauth/token" |
    python3 -c 'import sys,json; print(json.load(sys.stdin)["access_token"])'
}

# _gql TOKEN QUERY [VARIABLES_JSON] — one GraphQL call, prints the JSON reply.
_gql() {
  python3 - "$1" "$2" "${3:-{\}}" <<'PY'
import json, sys, urllib.request
token, query, variables = sys.argv[1], sys.argv[2], json.loads(sys.argv[3])
req = urllib.request.Request("https://api.linear.app/graphql",
    data=json.dumps({"query": query, "variables": variables}).encode(),
    headers={"Content-Type": "application/json", "Authorization": f"Bearer {token}"})
print(urllib.request.urlopen(req).read().decode())
PY
}

stage "Before you start"
say "This creates Max, the Engineering Manager agent, as an app in the KitCollective"
say "Linear workspace. What Max writes with it shows as the app, not as you, so a"
say "mention or an assignment from Max lands in your Linear inbox."
note "You need to be an admin of the KitCollective workspace."
note "Run this from the root of the main checkout; it writes ./.env there."
[[ -f factory.config.json ]] || { warn "factory.config.json not found: run this from the main checkout root."; exit 1; }
pause "Press Enter when you are signed in to Linear as an admin of KitCollective."

stage "Create the app in Linear"
open_url "https://linear.app/settings/api/applications/new"
step "Check the workspace switcher shows KitCollective (not the Optio workspace)."
step "Name: Max. Description: Engineering Manager agent of KitCollective's factory (staff/max.md)."
step "Developer name and URL: your own; any https URL is fine."
step "Callback URL: https://localhost/oauth/callback (required by the form, never used)."
step "Turn on client credentials (the toggle for client credentials tokens)."
step "Leave webhooks off and the app private, then create it."
note "Field names may differ slightly from these; the toggle for client credentials is the one that matters."
pause "Press Enter when the app exists and you can see its client ID and secret."

stage "Store the app's credentials"
say "Both values are on the app's page in Linear (Settings → API → your app)."
ask LINEAR_MAX_CLIENT_ID "Paste the client ID:"
ask_secret LINEAR_MAX_CLIENT_SECRET "Paste the client secret:"
[[ -n "$LINEAR_MAX_CLIENT_ID" && -n "$LINEAR_MAX_CLIENT_SECRET" ]] || { warn "Both values are needed."; exit 1; }
write_env LINEAR_MAX_CLIENT_ID "$LINEAR_MAX_CLIENT_ID"
write_env LINEAR_MAX_CLIENT_SECRET "$LINEAR_MAX_CLIENT_SECRET"
note "Only the client ID and secret are stored. Tokens are requested fresh per run and never written."

stage "Check who Max is"
say "Requesting a token with client credentials and asking Linear who it belongs to."
if ! MAX_TOKEN=$(_max_token); then
  warn "Linear refused the client credentials. Check the ID, the secret, and that client credentials are on."
  exit 1
fi
WHO=$(_gql "$MAX_TOKEN" '{ viewer { name } organization { urlKey } }')
MAX_NAME=$(printf '%s' "$WHO" | python3 -c 'import sys,json; d=json.load(sys.stdin)["data"]; print(d["viewer"]["name"])')
MAX_ORG=$(printf '%s' "$WHO" | python3 -c 'import sys,json; d=json.load(sys.stdin)["data"]; print(d["organization"]["urlKey"])')
say "Linear says this token is: ${BOLD}${MAX_NAME}${RESET} in workspace ${BOLD}${MAX_ORG}${RESET}"
if [[ "$MAX_ORG" != *kitcollective* ]]; then
  warn "That is not the KitCollective workspace. Delete the app and create it while KitCollective is selected."
  exit 1
fi
pause "Press Enter if the name is the app (Max), not you."

stage "Test: Max mentions you on an issue"
say "Max writes one comment on an issue you choose and mentions you in it."
say "If it reaches your Linear inbox, Max's identity works."
ask TEST_ISSUE "Issue to comment on (for example KIT-367):"
ME=$(_gql "$MAX_TOKEN" '{ users { nodes { displayName url active } } }' |
  python3 -c 'import sys,json; u=[n for n in json.load(sys.stdin)["data"]["users"]["nodes"] if n["displayName"]=="nicklas"]; print(u[0]["url"] if u else "")')
[[ -n "$ME" ]] || { warn "Could not find your Linear user (display name nicklas)."; exit 1; }
if confirm "Post the test comment on ${TEST_ISSUE} as Max?"; then
  BODY="Max: test of my own Linear identity, mentioning ${ME}. If this reached your Linear inbox, it works. This comment can be deleted."
  ISSUE_ID=$(_gql "$MAX_TOKEN" 'query($k:String!){ issue(id:$k){ id } }' "{\"k\":\"${TEST_ISSUE}\"}" |
    python3 -c 'import sys,json; print(json.load(sys.stdin)["data"]["issue"]["id"])')
  _gql "$MAX_TOKEN" 'mutation($i:CommentCreateInput!){ commentCreate(input:$i){ success } }' \
    "$(python3 -c 'import json,sys; print(json.dumps({"i":{"issueId":sys.argv[1],"body":sys.argv[2]}}))' "$ISSUE_ID" "$BODY")" >/dev/null
  say "Posted on ${TEST_ISSUE}."
  open_url "https://linear.app/${MAX_ORG}/inbox"
  pause "Press Enter once you have checked your Linear inbox for Max's mention."
else
  SKIPPED+=("test comment (not confirmed)")
fi
unset MAX_TOKEN

finish
